/*
 * E-ZERO Secure Pair V1 — isolated SQLite-backed Challenge Ledger LAB.
 * The SQL/transactionSync APIs match SQLite-backed Cloudflare Durable Objects.
 * NO route is attached to the public Worker. The caller must first perform
 * server-authenticated account/credential lookup and independently verify a
 * WebAuthn assertion/device signatures. Mere challenge consumption NEVER
 * authorizes pairing, reconnect, microphone, camera, or OBD actions.
 * All nonces must be randomly generated by a trusted server. Store HASHES only.
 */
export const CHALLENGE_MAX_AGE_MS=90_000;
const H32=/^[a-f0-9]{32}$/;
const H64=/^[a-f0-9]{64}$/;
const ACCOUNT=/^[A-Za-z0-9_-]{12,64}$/;
const CRED=/^[A-Za-z0-9_-]{8,256}$/;
function deny(code){return Object.freeze({ok:false,authorized:false,code});}
function good(code,fields={}){return Object.freeze({ok:true,authorized:false,code,...fields});}
function valid(fields,now){
 if(!fields||!Number.isSafeInteger(now))return false;
 const {sessionId,nonceDigest,accountId,credentialId,issued,expires,purpose}=fields;
 return typeof sessionId==="string"&&H32.test(sessionId)&&
  typeof nonceDigest==="string"&&H64.test(nonceDigest)&&
  typeof accountId==="string"&&ACCOUNT.test(accountId)&&
  typeof credentialId==="string"&&CRED.test(credentialId)&&
  purpose==="PAIR_OR_RECONNECT"&&Number.isSafeInteger(issued)&&
  Number.isSafeInteger(expires)&&issued>0&&issued<=now+30_000&&
  expires>now&&expires>issued&&expires-issued<=CHALLENGE_MAX_AGE_MS;
}
export class PairV1SqliteChallengeLedgerLab{
 #sql;#transactionSync;
 constructor(storage){
  if(typeof storage?.sql?.exec!=="function"||
     typeof storage?.transactionSync!=="function")
   throw Error("SQLITE_TRANSACTION_REQUIRED");
  this.#sql=storage.sql;
  this.#transactionSync=storage.transactionSync.bind(storage);
  // Should be run inside a DO initialization/migration gate before requests.
  this.#sql.exec(`CREATE TABLE IF NOT EXISTS ezero_pair_v1_challenges (
   session_id TEXT PRIMARY KEY,
   nonce_digest TEXT NOT NULL,
   account_id TEXT NOT NULL,
   credential_id TEXT NOT NULL,
   purpose TEXT NOT NULL CHECK(purpose='PAIR_OR_RECONNECT'),
   issued INTEGER NOT NULL,
   expires INTEGER NOT NULL,
   consumed_at INTEGER
  )`);
 }
 issue(fields,now=Date.now()){
  if(!valid(fields,now))return deny("ISSUE_INVALID");
  try{
   return this.#transactionSync(()=>{
    const {sessionId,nonceDigest,accountId,credentialId,purpose,issued,expires}=fields;
    // Unique primary key prevents duplicate/replayed session creation.
    const existing=this.#sql.exec(
     "SELECT session_id FROM ezero_pair_v1_challenges WHERE session_id=?",
     sessionId).toArray();
    if(existing.length)return deny("SESSION_ALREADY_EXISTS");
    this.#sql.exec(
     `INSERT INTO ezero_pair_v1_challenges
      (session_id,nonce_digest,account_id,credential_id,purpose,issued,expires)
      VALUES(?,?,?,?,?,?,?)`,
     sessionId,nonceDigest,accountId,credentialId,purpose,issued,expires);
    return good("SERVER_CHALLENGE_STORED_LAB");
   });
  }catch(_){return deny("LEDGER_UNAVAILABLE");}
 }
 consume({
  sessionId,nonceDigest,accountId,credentialId,purpose
 },now=Date.now()){
  if(!H32.test(sessionId||"")||!H64.test(nonceDigest||"")||
     !ACCOUNT.test(accountId||"")||!CRED.test(credentialId||"")||
     purpose!=="PAIR_OR_RECONNECT"||!Number.isSafeInteger(now))
   return deny("CONSUME_INVALID");
  try{
   return this.#transactionSync(()=>{
    // CAS-style update inside an SQLite transaction. Expired, wrongly bound,
    // or already consumed challenges all fail with the same public status.
    const result=this.#sql.exec(
     `UPDATE ezero_pair_v1_challenges SET consumed_at=?
      WHERE session_id=? AND nonce_digest=? AND account_id=?
       AND credential_id=? AND purpose=? AND consumed_at IS NULL
       AND issued<=? AND expires>?
      RETURNING session_id`,
      now,sessionId,nonceDigest,accountId,credentialId,purpose,now,now
    ).toArray();
    return result.length===1?
     good("CHALLENGE_CONSUMED_ONCE_LAB",{challengeConsumed:true}):
     deny("CHALLENGE_REJECTED_OR_REPLAYED");
   });
  }catch(_){return deny("LEDGER_UNAVAILABLE");}
 }
 // This method is intentionally NOT exposed as a public API. Trust requires
 // atomic account/device enrollment and revocation after passkey verification.
}
